<?php
require __DIR__ . '/mira-view-access.php';require __DIR__.'/event-common.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Exhibition not found');}
$s=$conn->prepare("SELECT title,description,venue,starts_at,ends_at,poster_path FROM events WHERE event_id=? AND status='published'");$s->bind_param('i',$id);$s->execute();$e=$s->get_result()->fetch_assoc();$s->close();if(!$e){http_response_code(404);exit('Exhibition not found');}
$s=$conn->prepare("SELECT a.artwork_id,a.title,u.FULL_NAME AS artist_name,(SELECT ai.image_path FROM artwork_images ai WHERE ai.artwork_id=a.artwork_id ORDER BY ai.image_id LIMIT 1) AS image_path FROM event_artworks ea JOIN artworks a ON a.artwork_id=ea.artwork_id JOIN users u ON u.USER_ID=a.user_id WHERE ea.event_id=? AND LOWER(a.status)='approved'");$s->bind_param('i',$id);$s->execute();$art=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=eventEsc($e['title'])?> | MIRA</title><script>try{document.documentElement.dataset.theme=localStorage.getItem('mira-theme')||'light'}catch(e){}</script><link rel="stylesheet" href="event.css"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-student-nav.css?v=2"><link rel="stylesheet" href="mira-design-system.css?v=1">
</head><body class="event-page"><?php require __DIR__ . "/mira-student-nav.php"; ?><main class="event-container"><p class="event-eyebrow">MIRA EXHIBITION</p><h1><?=eventEsc($e['title'])?></h1><?php if(!empty($e['poster_path'])):?><img class="event-detail-poster" src="<?=eventEsc($e['poster_path'])?>" alt="Exhibition poster"><?php endif;?><p><?=nl2br(eventEsc($e['description']))?></p><p class="event-muted"><?=eventEsc($e['venue'])?> · <?=eventEsc(date('M j, Y g:i A',strtotime($e['starts_at'])))?></p><?php if (!$miraAdminPreview && $miraAccountRole === 'ARTIST'): ?><p><a class="event-primary event-link-button" href="request-exhibition.php?event_id=<?=(int)$id?>">Request to exhibit my artwork</a></p><?php endif; ?><h2>Selected artwork</h2><section class="event-public-grid"><?php foreach($art as $a):?><a class="event-card event-artcard" href="artwork-view.php?id=<?=(int)$a['artwork_id']?>"><?php if(preg_match('~^uploads/artworks/[a-zA-Z0-9_-]+\.(jpg|jpeg|png|webp)$~i',(string)$a['image_path'])):?><img src="<?=eventEsc($a['image_path'])?>" alt="<?=eventEsc($a['title'])?>" loading="lazy"><?php endif;?><h3><?=eventEsc($a['title'])?></h3><p><?=eventEsc($a['artist_name'])?></p></a><?php endforeach;?><?php if(!$art):?><p class="event-card">No artworks have been selected yet.</p><?php endif;?></section></main></body></html>
